function ABLAM_SEARCH(problem, time_limit, params, seed)
    start ← now(); best ← null; archive ← ∅; Pool ← ∅; model ← InitOperatorWeights(problem)
    multipliers ← zero(constraint_count(problem)); hierarchy ← BuildMultilevelCoarsening(problem, params.levels)
    temperature ← InitTemperature(problem, time_limit); x_seed ← ConstructSeed(problem, seed, model); best_cost ← Eval(x_seed, multipliers)
    while not Termination(start, time_limit):
        frac ← RELAX_SOLVER(problem, multipliers, hierarchy.current_level, params, temperature)
        backbone ← ExtractBackbone(frac, thresh = AdaptiveThresh(temperature, params))
        modules ← ConstructModulesFromBackbone(problem, backbone, model, params)
        for m in Sample(modules, params.module_batch): Pool.add_if_new(m.signature → SolveModule(m, params))
        candidate ← AssembleFromPool(Pool, problem, backbone, params)
        if not Feasible(candidate): candidate ← Repair(candidate, problem, multipliers, backbone)
        candidate ← PATCH_AND_REFINE(candidate, model.SamplePatchers(), model.SampleLocalOperators(), params)
        cost ← Eval(candidate, multipliers); ArchiveUpdate(archive, candidate)
        if cost < best_cost and Validate(candidate): best, best_cost ← candidate, cost
        subgrad ← ComputeConstraintViolations(candidate, problem); multipliers ← UpdateMultipliers(multipliers, subgrad, params)
        AdaptModelAndHierarchy(model, archive, temperature, hierarchy, params); temperature ← Cool(temperature)
        if StagnationDetected(archive, params): Diversify(model, multipliers, hierarchy, Pool, params)
    return DECODE(best)

